{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw, ImageFont
img = Image.open('radiograph.jpg').convert('RGB')
d = ImageDraw.Draw(img)
W,H = img.size
for x in range(0, W, 100):
    d.line([(x,0),(x,H)], fill=(255,80,80), width=2 if x%500 else 4)
for y in range(0, H, 100):
    d.line([(0,y),(W,y)], fill=(80,160,255), width=2 if y%500 else 4)
try:
    f = ImageFont.load_default(30)
except:
    f = ImageFont.load_default()
for x in range(0, W, 500):
    for y in range(0, H, 500):
        d.text((x+6, y+6), f"{x},{y}", fill=(0,255,0), font=f)
img.save('crops/grid_full.png')
# also a version at half scale
img.resize((1222,646)).save('crops/grid_half.png')
print('ok')
EOF", "description": "Overlay labeled coordinate grid on radiograph"}
